import json, os
S = json.load(open('out/stat.json', encoding='utf-8'))
A = os.path.abspath
def ru(n, f1, f2, f5):
    n = abs(n) % 100; k = n % 10
    return f5 if 10 < n < 20 else f1 if k == 1 else f2 if 1 < k < 5 else f5
COMMON = ('Что нужно по каждому заказу из списка — до 5 декабря:\n'
          '1. Написать причину: почему заказ до сих пор открыт (отгружен, но не закрыт; клиент отказался; ждёт производства; ошибка в базе — как есть).\n'
          '2. Привести базу в порядок: закрыть заказ, если он неактуален, или указать реальный срок, если он живой.\n'
          '3. Ответить на это письмо: можно заполнить два жёлтых столбца в файле и прислать его обратно — это и будет письменное объяснение.\n\n'
          'К 5 декабря заказов старше 180 дней в базе быть не должно — это поручение Сотрудник2 Отчество2. Список собран по выгрузке 1С от 17.11.2026: если какой-то заказ вы уже закрыли, просто отметьте это в файле.\n\n'
          'До закрытия вопроса будем коротко напоминать раз в день — письмом и в боте. Если нужна помощь программистов 1С, напишите, передадим.\n\n'
          'Спасибо!\nПортал «Фабрика» по поручению Т. В. Сотрудник1')
def mk(key, to, cc, hello, intro):
    s = S[key]; n = s['n']
    d = {'to': to, 'subject': 'Открытые заказы старше 180 дней: %d %s — нужна причина и закрытие до 05.12' % (n, ru(n, 'заказ', 'заказа', 'заказов')),
         'text': hello + '\n\n' + intro + '\n\n' + COMMON, 'att': [A(s['file'])]}
    if cc: d['cc'] = cc
    json.dump(d, open('out/mail_%s.json' % key, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
    return d
